let s='';
process.stdin.on('data', d => s += d).on('end', () => {
  let c = '';
  try { const j = JSON.parse(s); c = (j.tool_input && j.tool_input.command) || ''; } catch {}
  const rules = [
    [/(?<!\buv\s{1,20})\bpip3?\s+install\b/, 'use uv instead of pip'],
    [/rm\s+-rf\s+\/(?![a-zA-Z])/, 'rm -rf / is forbidden'],
    [/taskkill[\s\S]*\/IM[\s\S]*(claude|node)\.exe/i, 'taskkill /IM claude.exe|node.exe kills EVERY Claude Code session machine-wide. Target a specific PID instead.'],
    [/\b(pkill|killall)\b[\s\S]*(claude|node)(?![a-zA-Z])/i, 'pkill/killall claude|node kills all sessions. Target a specific PID instead.']
  ];
  for (const [re, msg] of rules) {
    if (re.test(c)) { console.error('BLOCKED: ' + msg); process.exit(2); }
  }
});

let s='';
process.stdin.on('data', d => s += d).on('end', () => {
  let f = '';
  try { const j = JSON.parse(s); f = (j.tool_input && j.tool_input.file_path) || ''; } catch {}
  if (!/\.py$/i.test(f)) return;
  const bin = process.platform === 'win32' ? 'ruff.exe' : 'ruff';
  require('child_process').spawnSync(bin, ['format', f], { stdio: 'inherit' });
});
